import {request as lastLayerRequest,routines} from '../last-layer-efficiency-v1/policy';
import {decide as original,fullGoalRequest,type Ask} from '../brain-teaching-full-v1/policy';
import {decide as corners,actions as cornerActions} from '../efficiency-v1/corner-policy-v4';
import {decide as f2l} from './controller';
import type {Run,JevRequest} from '../../src/lib/types';
import type {PendingPlan} from '../plan-memory/policy';
export function goalRequest(run:Run):JevRequest{
 const request=structuredClone(fullGoalRequest(run));
 const criteria=request.questions.goal.criteria;
 delete criteria['first-layer'];delete criteria['middle-layer'];
 criteria.f2l='Solve the four yellow-corner/middle-edge pairs together. Choose when completed.cross=true and completed.middle=false. Preserve the completed cross and already solved pairs.';
 return request;
}
export async function decide(run:Run,ask:Ask,experience:unknown[]=[],excludedTarget:string|null=null,pendingPlan:PendingPlan|null=null){
 const request=goalRequest(run),response=await ask(request),goal=response.answers.goal.choice;
 if(goal==='f2l'){
  const d=await f2l(run.state,async r=>{
   if(excludedTarget&&r.questions.target){r=structuredClone(r);r.state={...r.state as object,excludedTarget};r.questions.target.instructions={teaching:r.questions.target.instructions,recovery:'JEV previously chose to change target. Choose an unfinished pair other than excludedTarget.'};}
   return ask(r);
  },run.stage==='f2l'?run.target:null,run.history.slice(-2));
  return {goal,target:d.target,front:d.front??'',skill:d.action,alg:d.alg,intent:d.preparation??d.action,f2l:d};
 }
 if(goal==='top-orientation'||goal==='top-edges'){
  const stage=goal==='top-orientation'?'orientation':'edges';
  const answer=await ask(lastLayerRequest(run.state,stage,'structured'));
  const action=answer.answers.routine.choice,routine=routines.find(r=>r.id===action);
  return {goal,target:'whole',front:routine?.front??'F',skill:action,alg:routine?.alg??'',intent:stage};
 }
 if(goal==='top-corners'){
  const action=await corners(run.state,'explicit',run.history.slice(-2),ask);
  return {goal,target:'whole',front:action.split('@')[1]??'F',skill:action,alg:cornerActions[action],intent:action==='done'?'done':action.startsWith('T@')?'permute':'align'};
 }
 let first=true;
 return original(run,async r=>{if(first){first=false;if(JSON.stringify(r)!==JSON.stringify(fullGoalRequest(run)))throw Error('Goal request drift');return response;}return ask(r);},experience,excludedTarget,pendingPlan);
}

import catalog from '../../experiments/last-layer-efficiency-v1/catalog.json';
import {pieces} from '../../src/lib/cube';
import type {CubeData,JevRequest} from '../../src/lib/types';
export type Stage='orientation'|'edges';
export type Variant='structured'|'sentences';
export const routines=catalog.rows;
export function observation(state:CubeData,stage:Stage){return Object.fromEntries(pieces(state).filter(p=>p.position.includes('U')&&p.kind===(stage==='orientation'?'corner':'edge')).map(p=>[p.position,stage==='orientation'?p.stickers.white:p.destination]));}
export function request(state:CubeData,stage:Stage,variant:Variant):JevRequest{
 const pattern=observation(state,stage),describe=(p:Record<string,string|undefined>)=>Object.entries(p).map(([slot,value])=>stage==='orientation'?`At ${slot}, white faces ${value}.`:`The edge at ${slot} belongs at ${value}.`).join(' ');
 return {model:'jev-1.13.0',state:variant==='structured'?{pattern}:{observation:describe(pattern)},questions:{routine:{type:'choice',instructions:stage==='orientation'?'Choose the learned orientation routine whose reference matches all four white sticker directions. Coordinates are the fixed cube frame. Each option already names its reference front and fixed turns. Lower layers and white-up edges finish unchanged. Do not use other corner colors or destinations.':'Choose the learned edge permutation whose reference matches all four current-position/destination pairs. Coordinates are the fixed cube frame. Match current positions, not just which pieces participate. All corners and lower layers finish unchanged.',criteria:{...Object.fromEntries(routines.filter(r=>r.stage===stage).map(r=>[r.id,`${describe(r.pattern)} Execute ${r.alg} (${r.turns} face turns), reference front ${r.front}.`])),done:stage==='orientation'?'Every white sticker already faces U.':'Every edge is already at its own destination.',reconsider:'None of the reference patterns matches all four observations.'}}}};
}

