import {pieces,colors,mapAlg} from '../../src/lib/cube';
import {skills} from '../../src/lib/skills';
import type {CubeData,JevRequest} from '../../src/lib/types';
export const variants=['explicit','relational','minimal'] as const;
export type Variant=typeof variants[number];
export const actions=Object.fromEntries(['F','R','B','L'].flatMap(front=>['middle-right','middle-left'].map(id=>[`${id}@${front}`,mapAlg(skills.find(s=>s.id===id)!.alg,front)])));
Object.assign(actions,{U:'U',"U'":"U'",U2:'U2',leave:''});
const intentOptions={done:'Leave this piece in place',align:'Align this upper edge with a side center',insert:'Insert this upper edge into the middle layer',extract:'Bring this middle edge into the upper layer'};
const routines='A right insertion takes the edge at local UF into FR: its front-facing color matches the front center and its up-facing color matches the right center. Left insertion similarly takes UF into FL with the up-facing color matching the left center. Either routine ejects the previous occupant of that middle slot into the upper layer, and restores the bottom layer. Upper turns reposition upper pieces without moving middle or bottom pieces. A piece is solved only when both stickers match their centers, including orientation.';
const rules='If both stickers match their centers choose done. Otherwise a middle edge needs extract. An upper edge needs insert when its side-facing sticker matches the adjacent center, otherwise align. For insert choose front matching the side-facing color, then right or left according to the up-facing color. For extract use the CURRENT occupied slot, not its home: FR -> middle-right@F or middle-left@R; BR -> middle-right@R or middle-left@B; BL -> middle-right@B or middle-left@L; FL -> middle-right@L or middle-left@F. For align choose U/U\'/U2 to match the side sticker to its center. done requires leave.';
export function request(state:CubeData,target:string,variant:Variant,intention?:string):JevRequest {
 const p=pieces(state).find(p=>p.piece===target)!;
 const faceWords:Record<string,string>={U:'up',D:'down',F:'front',R:'right',B:'back',L:'left'};
 const teaching=variant==='minimal'?'The listed sequences are standard middle-layer insertions in the named front frame.':routines;
 return {model:'jev-1.13.0',state:{centers:colors,target:{position:p.position,currentLayer:p.position.includes('U')?'upper':'middle',currentLocation:[...p.position].map(f=>faceWords[f]).join(' / '),stickers:p.stickers,visibleStickers:Object.entries(p.stickers).map(([color,f])=>({color,facing:faceWords[f],adjacentCenter:colors[f]}))},goal:'Solve the selected edge with both stickers matching centers. This piece belongs in the middle layer eventually; its current location is given separately. Preserve the completed bottom layer after a complete action. Choose one useful next action, possibly preparation.',frame:'Fixed U up, D down, F front, R right, B back, L left. For routines, @face names the local front; U/D stay fixed. Turns are clockwise as viewed directly at the turned face.',...(intention===undefined?{}:{previousIntention:intention})},questions:{...(intention===undefined?{location:{type:'choice' as const,instructions:'Where is the selected piece NOW? Use current location only, not where it belongs. This question is independent of intention.',criteria:{upper:'Currently in the upper layer',middle:'Currently in the middle layer'}}}:{}),[intention===undefined?'intention':'action']:{type:'choice',instructions:[teaching,variant==='explicit'?rules:'Infer the appropriate next step from the observed relationships and the routine reference.',intention===undefined?'Choose the immediate intention.':'Choose one action carrying out previousIntention. Earlier model answers are not guaranteed correct; no replacement answer is supplied.'].join(' '),criteria:intention===undefined?intentOptions:Object.fromEntries(Object.entries(actions).map(([id,alg])=>[id,id==='leave'?'Leave the cube unchanged':`${id}: ${alg}`]))}}};
}

