  {id:'cross-flip-bottom',alg:"F L' U2 L F'",stages:['cross'],purpose:'Target at DF with yellow pointing F: lift it to UR yellow-up, preserving the OTHER three bottom edges. The target bottom slot itself is unsolved.'},

  {
    id: 'lift-bottom',
    alg: 'F2',
