import {goalObservation} from '../../src/server/goal-policy';
import {facts,pieces} from '../../src/lib/cube';
import type {Run,JevRequest} from '../../src/lib/types';
export const goalDefinitions={
 daisy:'Gather yellow edges as top petals. Choose when cross=false and uncollectedYellowEdges>0. Preserve solved bottom edges and existing petals.',
 cross:'Transfer yellow-up petals to their bottom homes. Choose when cross=false and uncollectedYellowEdges=0. This controller only transfers petals; it cannot extract or gather missing petals.',
 'first-layer':'Solve yellow corners. Choose when cross=true and firstLayer=false.',
 'middle-layer':'Solve middle edges. Choose when firstLayer=true and middle=false.',
 'top-cross':'Orient white top edges. Choose when middle=true and topCross=false.',
 'top-orientation':'Orient white top corners. Choose when middle=true, topCross=true and topOriented=false.',
 'top-corners':'Place or align white corners. Choose when middle=true, topCross=true, topOriented=true and cornersPlaced=false.',
 'top-edges':'Place or align remaining white edges. Choose when middle=true, topCross=true, topOriented=true, cornersPlaced=true and solved=false.',
};
export function fullGoalRequest(run:Run,variant:'compact'|'detailed'='compact'):JevRequest{
 const completed=facts(run.state);
 const uncollectedYellowEdges=pieces(run.state).filter(p=>p.kind==='edge'&&'yellow'in p.stickers&&p.stickers.yellow!=='U'&&!p.solved).length;
 const state=variant==='detailed'?{...goalObservation(run.state,run.history.length?run.stage:null,run.history),uncollectedYellowEdges}:{completed,uncollectedYellowEdges,previousGoal:run.history.length?run.stage:null,recentActions:run.history.slice(-2)};
 return {model:'jev-1.13.0',state,questions:{goal:{type:'choice',instructions:'Choose the goal whose prerequisites match the current measurements. Apply the fixed definitions in the options. uncollectedYellowEdges counts yellow edges that are neither yellow-up petals nor solved bottom edges. PreviousGoal is memory, not an instruction; choose using present conditions. Completion flags describe structures, not recommendations. The program stops separately when all pieces are solved.',criteria:goalDefinitions}}};
}

sources.scripts/efficiency-v1/corner-policy-v4.t:
import {decide as base,actions} from './corner-policy-v3';
import type {CubeData,JevRequest,JevResponse} from '../../src/lib/types';
export {actions};
export type Variant='explicit'|'isolated';
export async function decide(state:CubeData,variant:Variant,history:string[],ask:(r:JevRequest)=>Promise<JevResponse>){
 return base(state,'words',history,async(original)=>{
  const r=structuredClone(original);
  if(!r.questions.intention)return ask(r);
  r.questions.intention.instructions='pairCount is the number of sides whose two upper-corner stickers have the same color. Use pairCount to choose the operation family. With pairCount=0 or 1 choose permute. With pairCount=4 compare each pair color to its own center: all match means done, otherwise align.';
  r.questions.intention.criteria={permute:'pairCount=0 or pairCount=1.',align:'pairCount=4, and at least one pair color differs from its own center.',done:'pairCount=4, and each pair color equals its own center.'};
  if(variant==='explicit')return ask(r);
  const first=await ask({...r,questions:{intention:r.questions.intention}});
  if(first.answers.intention.choice==='done')return first;
  const key=first.answers.intention.choice==='permute'?'reference':'destination';
  const second=await ask({...r,questions:{[key]:r.questions[key]}});
  return {...first,answers:{...first.answers,...second.answers}};
 });
}

sources.scripts/efficiency-v1/corner-policy-v3.t:
import {observe,actions} from './corner-policy';
import type {CubeData,JevRequest,JevResponse} from '../../src/lib/types';
export {actions};
export type Variant='letters'|'words';
const ring=['F','R','B','L'];
const names:Record<string,string>={F:'front',R:'right',B:'back',L:'left'};
export async function decide(state:CubeData,variant:Variant,history:string[],ask:(r:JevRequest)=>Promise<JevResponse>){
 const observation=observe(state);
 const pairColors=Object.fromEntries(ring.map(f=>{const c=observation.sides[f].cornerStickers;return [f,c[0].color===c[1].color?c[0].color:'mixed'];}));
 const pairCount=Object.values(pairColors).filter(x=>x!=='mixed').length;
 const result=await ask({model:'jev-1.13.0',state:{pairColors,pairCount,centers:Object.fromEntries(ring.map(f=>[f,observation.sides[f].center])),recentActions:history.slice(-2)},questions:{
  intention:{type:'choice',instructions:'Choose the next intention for placing upper corners. Pairs compare the two corner colors on a side with each other, not with its center. Ignore upper edges.',criteria:{done:'All four pair colors already match their own side centers.',align:'Four matching pairs exist but their colors do not match their own centers. Rotate the upper layer to align.',permute:'Zero or one matching pair exists. Use a T permutation to rearrange corners.'}},
  reference:{type:'choice',instructions:'Independently assume a T permutation is needed. Choose the front that places the matching pair on local LEFT. If no pair exists or all four exist, any reference is acceptable. Do not read sibling answers.',criteria:Object.fromEntries(ring.map((f,i)=>[f,`Local front ${f}, local left ${ring[(i+3)%4]}. Fits if pairColors.${ring[(i+3)%4]} is not mixed, or no pair exists.`]))},
  destination:{type:'choice',instructions:'Independently find where the pair currently on F belongs. Compare pairColors.F with each center. Return the face whose center has that color, or none if pairColors.F is mixed. Do not choose a turn and do not read sibling answers.',criteria:{F:'The center on F matches pairColors.F.',R:'The center on R matches pairColors.F.',B:'The center on B matches pairColors.F.',L:'The center on L matches pairColors.F.',none:'The pair on F is mixed.'}}
 }});
 const a=result.answers;
 // Branch only on model answers. No tactical verification or repair.
 if(a.intention.choice==='done')return 'done';
 if(a.intention.choice==='permute')return 'T@'+a.reference.choice;
 const destination=a.destination.choice;
 const turn=await ask({model:'jev-1.13.0',state:{currentPosition:variant==='words'?'front':'F',requiredPosition:variant==='words'?(names[destination]??destination):destination},questions:{turn:{type:'choice',instructions:'Choose the upper-face rotation that carries currentPosition to requiredPosition. Source and destination are an ordered pair. Choose leave if they are the same or requiredPosition is none.',criteria:variant==='words'?{
 U:'Quarter turn: front to left; left to back; back to right; right to front.',
 "U'":'Quarter turn: front to right; right to back; back to left; left to front.',
 U2:'Half turn: front to back, back to front, left to right, or right to left.',leave:'No rotation: same source/destination or destination none.'
 }:{U:'F to L; L to B; B to R; R to F.',"U'":'F to R; R to B; B to L; L to F.',U2:'F to B; B to F; R to L; L to R.',leave:'Same source/destination, or destination none.'}}}});
 return turn.answers.turn.choice==='leave'?'done':turn.answers.turn.choice;
}

